ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

WITH ins_art_3_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b23$مواعيد إعداد وتقديم القوائم المالية السنوية وربع السنوية للشركات التي تزاول
 نشاط التأمين :
تلتزم الشركات المخاطبة بأحكام هذا القرار بموافاة الهيئة بالقوائم المالية السنوية
المستقلة )والمجمعة بالنسبة للشركات الملزمة بإعداد قوائم مالية مجمعة( والإفصاحات
المرفقة بها وفق معايير المحاسبة المصرية وتقرير مراقب الحسابات بشأنها مرفق ًا بها
تقرير مجلس الإدارة قبل شهر من موعد انعقاد الجمعية العامة ،وللهيئة إبداء
ملاحظاتها على تلك القوائم وكذا على أي من البيانات والمستندات الواردة بهذا القرار
وإخطار الشركة بملاحظاتها ،على أن يعرض ذلك على الجمعية العامة للشركة وذلك
خلال ثلاثة أشهر من انتهاء السنة المالية ،وفي حال تعديل الجمعية العامة للقوائم
المالية فيجب موافاة الهيئة بصورة من القوائم المالية المعدلة مرفق ًا بها تقرير مراقب
الحسابات عن تلك القوائم خلال ) (١٥يوما من تاريخ انعقاد الجمعية العامة التي عدلت
 القوائم المالية .
كما تلتزم الشركات المشار إليها بموافاة الهيئة بالقوائم المالية ربع السنوية
)الدورية( المستقلة )والمجمعة بالنسبة للشركات الملزمة بإعداد قوائم مالية مجمعة(
مرفق ًا بها تقرير فحص محدود من مراقب الحسابات خلال ) (٤٥يوما من نهاية الفترة
 المقدم عنها القوائم المالية .$b23$
  FROM laws WHERE law_no = 3 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
