WITH ins_art_5_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b32$تضاف فقرتان جديدتان إلى المادة السابعة من قرار مجلس إدارة الهيئة
 رقم ١٧٨لسنة ۲۰۲٤المشار إليه ،نصهما الآتي :
 )المادة السابعة /الفقرة الثانية( :
ومع عدم الإخلال بالفقرة السابقة ،في حال رغبة شركتين أو أكثر من شركات
التأمين التي تزاول نفس نوع النشاط في مصر في الاندماج ،فيجب الحصول على
موافقة الجمعية العامة غير العادية لتلك الشركات على الاندماج بشكل نهائي ،وإذا
كان الاندماج سيتم بناء على عملية استحواذ فيجب موافقة الجمعية العامة غير العادية
للشركات الراغبة في الاندماج على النحو المشار إليه خلال شهرين من تاريخ
٣ الوقائع المصریة – العدد ٣٣تابع )أ( فى ١٠فبرایر سنة ٢٠٢٥
الاستحواذ وأن يكون الاستحواذ بالنسب التي تمكن الشركة من السير في إجراءات
الاندماج سواء تم الاستحواذ من خلال اتفاق مع مساهم بمفرده أو مع أطرافه المرتبطة
أو أي مساهمين آخرين على أن يتم تنفيذ الاندماج خلال ستة أشهر بحد أقصى من
تاريخ تقديم الطلب للهيئة ،ويجوز للهيئة مد هذه المدة بناء على مبررات تقدمها
الشركة وتقبلها الهيئة .ولا يجوز خلال الفترة من تاريخ الاستحواذ وحتى إتمام
الاندماج التصرف في الأسهم المستحوذ عليها أو التصويت بها إلا لأغراض الاندماج
أو لتسيير أعمال الشركة وفقا ً للتشريعات المعمول بها مع وجوب الحصول على عدم
 ممانعة مسبقة من الهيئة بشأن الدعوة لاجتماع الجمعية العامة المشار إليها .
 )المادة السابعة /الفقرة الثالثة( :
وفي حال مخالفة الفقرة السابقة ،توقف حقوق التصويت وتوزيعات الأرباح
الخاصة بأسهم الشركة المستحوذة في الشركة المستحوذ عليها ،ويتعين على الشركة
المستحوذة في هذه الحالة التصرف في النسبة المشتراة خلال ثلاثة أشهر من تاريخ
المخالفة ،وإلا كان للهيئة الأمر بتعيين إحدى شركات السمسرة في الأوراق المالية
لتولي إجراءات بيع الأسهم المشتراة على أن تؤول حصيلة البيع للمساهم بعد خصم
 المصروفات .$b32$
  FROM laws WHERE law_no = 5 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
