  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 16, NULL, $b65$تبدأ السنة المالية للصندوق فى أول يناير وتنتهى فى ٣١ديسمبر من كل سنة ،
ويكون للصندوق قوائم مالية سنوية يتم إعدادها وفق ًا لدليل تطبيق معايير المحاسبة
المصرية على صناديق التأمين الخاصة التى تصدرها الهيئة ،وعلى المسئولين
عن إدارة الصندوق أن يمسكوا حسابات منتظمة تتناول إيرادات الصندوق ومصروفاته
 وعناصر مركزه المالى .
ويلتزم الصندوق بأن يقدم للهيئة قبل ثلاثين يوما من التاريخ المحدد لانعقاد
الجمعية العامة تقريرا عن نشاطه مرفق ًا به قائمة بمركزه المالى وقائمة بحساب
إيراداته ومصروفاته وتقرير مراقب الحسابات ،وكذا بيان بمدد الاشتراكات الجديدة
وقيمتها وعدد المشتركين الذين توقفوا خلال العام عن سداد اشتراكاتهم وذلك
على النموذج الذى تعده الهيئة لهذا الغرض ،وذلك كله بما لا يخل بالتزام الصندوق
 بعقد الجمعية العامة فى موعد أقصاه ثلاثة أشهر من انتهاء السنة المالية .$b65$
  FROM laws WHERE law_no = 236 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
