WITH ins_art_alamiria_2024_236_17 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 17, NULL, $b66$يكون للصندوق مراقب حسابات أو أكثر من بين المقيدين بسجل مراقبى
 الحسابات لدى الهيئة وفق ًا للضوابط الصادر بشأنها قرار من مجلس إدارة الهيئة .
ويتم تعيين مراقب الحسابات وتحديد أتعابه بقرار من الجمعية العامة للصندوق
بناء على ترشيح من مجلس إدارته ،ويكون الترشيح من ضمن ممن تتوافر فى شأنهم
 الشروط والكفاءة والسمعة والخبرة الكافية المتناسبة مع حجم وطبيعة نشاط الصندوق .
وعلى مراقب الحسابات التحقق من التزام الصندوق بمعايير المحاسبة المصرية
عند إعداد القوائم المالية ،كما يلتزم بمعايير المراجعة المصرية عند قيامه بالمراجعة
 أو الفحص المحدود للقوائم المالية وعند إعداد تقاريره .
ويجب دعوة مراقب الحسابات لحضور اجتماعات الجمعية العامة للصندوق ،
وكذا اجتماعات مجلس إدارته التى يتم مناقشة حسابات الصندوق بها أو أى جلسة أخرى
 يقرر مجلس الإدارة دعوته لحضورها لاستطلاع رأيه فيما يدخل من اختصاصاته من أمور .
١٥ الوقائع المصریة – العدد ٢٥٧تابع )ب( فى ١٩نوفمبر سنة ٢٠٢٤
وإذ تعدد مراقبو حسابات الصندوق يكون لكل منهم حق الاطلاع على دفاتر
الصندوق وطلب البيانات والإيضاحات وتحقيق الموجودات والالتزامات ،ومع ذلك
يجب أن يقدم مراقبو الحسابات تقريرا موحدا وفى حالة الاختلاف فيما بينهم يوضح
 التقرير أوجه الخلاف ووجهة نظر كل منهم .
وفى جميع الأحوال ،لا يجوز التعاقد مع مراقب الحسابات لأداء أى أعمال
 إضافية للصندوق إلا بعد موافقة الجمعية العامة للصندوق .$b66$
  FROM laws WHERE law_no = 236 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
