WITH ins_art_alamiria_2024_236_18 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 18, NULL, $b67$يقدم الصندوق تقريرا اكتواريا إلى الهيئة بمركزه المالى يعده أحد الخبراء
الاكتواريين المسجلين لدى الهيئة مرة كل خمس سنوات على الأكثر يوضح فيه مدى
كفاية أموال الصندوق لمقابلة التزاماته وفق ًا للأسس الفنية التى تعتمدها الهيئة فى هذا
الشأن ،ويتم إعداد هذا التقرير وفق ًا للشروط والضوابط التى يصدرها مجلس إدارة
الهيئة ،ولمجلس إدارة الهيئة أن يطلب تقديم هذا التقرير فى أى وقت قبل مضى
 خمس سنوات بحيث لا تقل المدة عن سنة من تاريخ آخر تقرير .
ويجب إرسال صورة من التقرير إلى الهيئة خلال ستة أشهر من انتهاء الفترة
التى أعد عنها التقرير مصحوبة بشهادة من الخبير الاكتوارى تثبت أن المسئولين عن
إدارة الصندوق قد وضعوا تحت تصرفه جميع البيانات والمعلومات التى طلبها ويراها
ضرورية لأداء مهامه ،ويلتزم الخبير بإخطار الهيئة بأى خطأ أو مخالفات قد تتكشف لديه
 أثناء إعداد التقرير الاكتوارى ،وللهيئة مد هذا الميعاد لفترة لا تتجاوز ثلاثة أشهر .
وإذا تبين للهيئة أن تقرير الخبير الاكتوارى لا يعبر عن حقيقة المركز المالى
للصندوق فلها أن تأمر بإعادة إعداد التقرير بواسطة خبير اكتوارى آخر على نفقة
 الصندوق ،ويلتزم الصندوق فى جميع الحالات بنفقات إعادة الفحص .$b67$
  FROM laws WHERE law_no = 236 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
