WITH ins_art_alamiria_2024_236_48 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 48, NULL, $b97$توثق اجتماعات مجلس إدارة الصندوق من خلال إعداد محضر اجتماع لكل
جلسة يتضمن مكان وتوقيت الاجتماع وإثبات حضور أعضاء المجلس والموضوعات
التى تم مناقشتها بالاجتماع وملخصا لمناقشات أعضاء المجلس والقرارات المتخذة
فى هذا الشأن وإثبات ما يبديه الأعضاء من تحفظات على أن يكون لعضو مجلس
الإدارة حال رفض إثبات تحفظه تقديم شكوى للهيئة مثبت ًا بها مضمون التحفظ خلال
 أسبوع على الأكثر من تاريخ الاجتماع .
 ويجب توقيع المحضر من رئيس المجلس وكافة أعضاء المجلس الحاضرين .
ويكون لكل عضو من أعضاء مجلس الإدارة طلب الاطلاع على أى محضر
 من محاضر مجلس الإدارة .
ويلتزم الصندوق بإرفاق محضر اجتماع مجلس الإدارة بعد استيفاء كافة
 التوقيعات المتطلبة قانون ًا عليه ،بسجل محاضر اجتماعات مجلس إدارة الصندوق .
ويجوز للصندوق حفظ محاضر اجتماعات مجلس الإدارة من خلال سجلات
الكترونية بما يسمح بتخزينها وتوثيقها والاحتفاظ بها وعدم تغييرها واستخراجها بشكل
 يسهل الرجوع إليها ،ويضع الصندوق ضوابط ذلك بمراعاة ما يلى :
) أ ( أن يكون المحضر موقعا الكترونيا وفق ًا لأحكام القانون رقم ١٥لسنة ٢٠٠٤
 الصادر بشأن تنظيم التوقيع الإلكترونى .
)ب( أن يتوافر فى السجل الإلكترونى تقنيات وأنظمة تكفل أمن المعلومات وعدم
 الاختراق على النحو الذى تحدده الهيئة .$b97$
  FROM laws WHERE law_no = 236 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
