  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 51, NULL, $b100$يجوز بقرار من الهيئة الترخيص للصندوق بناء على طلبه الاندماج أو تحويل
أمواله فى صندوق أخر أو إلى وثيقة تأمين جماعية لدى إحدى شركات التأمين العاملة
فى جمهورية مصر العربية وذلك بشرط موافقة الجمعية العامة غير العادية لكل
صندوق وفق ًا للأغلبية المنصوص عليها فى المادة ) (۸۳من قانون التأمين الموحد ،
ويعتبر الصندوق المندمج فيه خلف ًا للصندوق المندمج ،ويحل محله حلولا ً قانونيا فيما
 له من حقوق وما عليه من التزامات .
 ويتم الاندماج أو التحويل وفق ًا للقواعد والإجراءات التى يحددها مجلس إدارة الهيئة .$b100$
  FROM laws WHERE law_no = 236 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
