-- ===== alamiria_2024_237 : قرار 237/2024 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (237, 2024, $t109$بشأن ضوابط تسجيل وتصفية وشطب صناديق التأمين الخاصة والشروط الواجب توافرها فى النظام الأساسي لتلك الصناديق وضوابط تعديلها$t109$, $t109$بشأن ضوابط تسجيل وتصفية وشطب صناديق التأمين الخاصة والشروط الواجب توافرها فى النظام الأساسي لتلك الصناديق وضوابط تعديلها$t109$, 'insurance', 'in_force', $u109$https://fra.gov.eg/wp-content/uploads/2024/11/alamiria_2024_237.pdf$u109$, NULL)
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

WITH ins_art_alamiria_2024_237_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b110$تسرى أحكام هذا القرار فى شأن ضوابط تسجيل وتصفية وشطب صناديق
التأمين الخاصة ،والشروط الواجب توافرها فى النظام الأساسى لتلك الصناديق
 وضوابط تعديلها .$b110$
  FROM laws WHERE law_no = 237 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b110$تسرى أحكام هذا القرار فى شأن ضوابط تسجيل وتصفية وشطب صناديق
التأمين الخاصة ،والشروط الواجب توافرها فى النظام الأساسى لتلك الصناديق
 وضوابط تعديلها .$b110$, now()::date, 'active' FROM ins_art_alamiria_2024_237_1;
WITH ins_art_alamiria_2024_237_2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b111$ضوابط تسجيل صناديق التأمين الخاصة لدى الهيئة
يقدم المفوض من مؤسسى صندوق التأمين الخاص طلب تسجيل الصندوق لدى
 الهيئة على النموذج المعد منها لهذا الغرض مرفق ًا به المستندات الآتية :
 -۱نسختان معتمدتان من النظام الأساسى للصندوق .
 -٢الدراسة الإكتوارية المعدة من أحد الخبراء الإكتواريين المسجلين لدى الهيئة
 وفق ًا للشروط والضوابط والقواعد التى يحددها مجلس إدارة الهيئة .
