WITH ins_art_alamiria_2024_298_3 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 3, NULL, $b134$التزامات الشركة الراغبة فى التعاقد مع المتدرب
تلتزم الشركات الراغبة فى التعاقد مع متدربين على أعمال الوساطة التأمينية
 بما يلى :
 -١إبرام عقد ينظم الحقوق والالتزامات بين الطرفين وبما يتوافق مع أحكام
قانون التأمين الموحد والقرارات الصادرة من الهيئة لتنظيم ممارسة نشاط الوساطة
فى التأمين ،على أن يتضمن العقد أحقية المتدرب فى الحصول على مزايا مالية
ومكافأة عن العمليات التى ساهم فى جلبها للشركة ،ويجب على الشركة موافاة الهيئة
 بنموذج العقد المشار إليه قبل إبرامه للحصول على عدم ممانعتها عليه .
 -٢ألا تزيد مدة عمل المتدرب الفعلية على سنتين ،وعلى الشركة منح المتدرب
فى نهاية المدة إفادة باجتيازه فترة التدريب بنجاح ،كما تلتزم الشركة إذا ارتأت عدم
اجتياز المتدرب الفترة المشار إليها بإخطاره وكذا إخطار الهيئة بأسباب ذلك خلال
 أسبوع من نهاية فترة عمله كمتدرب .
 الوقائع المصریة – العدد ١٩تابع )أ( فى ٢٣ینایر سنة ٢٠٢٤ ٤
ويجوز للمتدرب العمل خلال المدة المشار إليها لدى شركتين بحد أقصى على
 ألا يعمل لديهما فى ذات الوقت .
 -٣أن يعمل المتدرب تحت إشراف وسيط تأمين مسجل بالهيئة بالجهاز الإنتاجى
بالشركة ،على ألا يزيد عدد المتدربين تحت إشراف وسيط تأمين واحد على
 عشرة متدربين .
 -٤أن تكون الشركة والوسيط مسئولين عن أعمال المتدرب والأخطاء التى
 يرتكبها المتعلقة بممارسته لأعماله .
 -٥وضع برنامج تدريب وتأهيل عملى ونظرى للمتدرب مع موافاة الهيئة
 بتفاصيل ذلك البرنامج .
 -٦أن يقترن اسم المتدرب باسم الوسيط المسئول عنه فى طلب التأمين والوثيقة
فيما يتعلق بالعمليات التى قام المتدرب بجلبها ،على أن يكتب اسم المتدرب قرين اسم
 الوسيط بسجل الوثائق الذى تمسكه الشركة .
وفى جميع الأحوال ،على الشركات المخاطبة بأحكام هذا القرار إخطار الهيئة -
على النموذج المعد منها لهذا الغرض -عند ترك المتدرب للشركة وأسباب ذلك
 أو انتقاله للعمل إليها ،وذلك خلال عشرة أيام من تاريخ الترك أو الانتقال بحسب الأحوال .$b134$
  FROM laws WHERE law_no = 298 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
