-- ===== alamiria_2026_2036-R : قرار 2036/2026 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (2036, 2026, $t198$بشأن معايير إدارة المخاطر فى الاكتتاب لعمليات تأمينات الأشخاص الفردي$t198$, $t198$بشأن معايير إدارة المخاطر فى الاكتتاب لعمليات تأمينات الأشخاص الفردي$t198$, 'insurance', 'in_force', $u198$https://fra.gov.eg/wp-content/uploads/2026/07/alamiria_2026_2036-R.pdf$u198$, NULL)
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

WITH ins_art_alamiria_2026_2036_R_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b199$تلتزم كافة شركات تأمينات الأشخاص عند الاكتتاب في وثائق التأمين الفردي
 بما يلي :
 -١إعداد نموذج طلب التأمين بغرض استيفاء كافة البيانات الأساسية الخاصة
بطالب التأمين ،ومنها الإفصاحات التفصيلية المتعلقة بحالته الصحية ووضعه المالي،
 بما يمكن الشركة من تقييم مخاطر العملاء بشكل صحيح .
 - ٢قيام طالب التأمين باستيفاء طلب التأمين وكافة البيانات الواردة به بنفسه،
والتوقيع عليه بكتابة اسمه كاملا ً على كافة أوراق الطلب ،مع ضرورة قيامه بالتوقيع
 بجانب أي تعديلات تطرأ على بيانات ذلك الطلب .
 -٣التأكد من هوية طالب التأمين ومن سلامة المستندات المقدمة للشركة قبل
قيامها بإصدار وثائق التأمين ،بما يمكنها من التحقق من صحة المعلومات التي قام
 طالب التأمين بالإفصاح عنها .
٣ الوقائع المصریة – العدد ١٥٢تابع ) أ ( فى ١٥یولیة سنة ٢٠٢٦
 -٤الاستعلام عن الموقف الائتماني لطالب التأمين الراغب في إبرام وثائق
تأمين بمبالغ تأمين تبلغ ١٠ملايين جنيه مصري )أو ما يعادلها بالعملات الأجنبية(
فأكثر من خلال جهات الاستعلام الائتمائي المرخص لها بذلك ،وكذلك حال عدم
تناسب دخل أو مهنة/وظيفة العميل مع قيمة مبلغ التأمين أو قيمة الأقساط الملتزم
 بسدادها ،أو في حال وجود شكوك فيما يتعلق بمدى مشروعية طلب التأمين.
 -٥الاستعلام عما إذا كان طالب التأمين مدرجا بالقوائم السلبية من عدمه.
 -٦الاستعلام عما إذا كان لطالب التأمين وثائق تأمين سابقة والتعرف على
 مدى التزامه بأحكامها ،وذلك من خلال الأنظمة المعدة لذلك الغرض.
 -٧التحقق من صحة بيانات ملكية رقم الهاتف المحمول لطالب التأمين ،من
خلال أنظمة الاستعلام المعدة لذلك الغرض وفق ًا لقرار مجلس إدارة الهيئة رقم ١٨٦
 لسنة ٢٠٢٤الصادر في هذا الشأن.
 -٨إعداد الأنظمة والسياسات التي تمكن الشركة ووسطاء التأمين بالجهاز
 الإنتاجي لديها من الآتي :
)أ( التأكد من مدى تناسب وثيقة التأمين ومبالغها ومستوى دخل طالب التأمين
مع المتوسطات الناتجة عن نشاط الشركة وفق ًا لذات طبيعة الخطر في المنطقة
الجغرافية للمؤمن عليه من ذات شركات التأمين ،وفي حال عدم التناسب يجب على
الشركة إعداد الدراسات اللازمة التي تمكنها من تقليل احتمالات الغش أو الاحتيال
 ومنها التعرف على التاريخ الائتماني للعميل وغيرها من المؤشرات.
)ب( التعرف على حالات تكرار ذات المخاطر المؤمن عليها لذات المؤمن له،
ويجب على الشركة إعداد دراسة شاملة للتحقق من مدى مشروعية هذه الطلبات
 وتخفيض احتمالات الغش والاحتيال بها.
)ج( تحديد مدى ظهور حالات لمخاطر محددة يتم التأمين ضدها من مؤمن له
أو أكثر ،ويجب على الشركة دراسة وتحديد ما إذا كان هناك ارتباط جغرافي
 أو اجتماعي أو زمني ما بين المؤمن لهم ضد تلك المخاطر من عدمه.
 الوقائع المصریة – العدد ١٥٢تابع ) أ ( فى ١٥یولیة سنة ٢٠٢٦ ٤
وفي جميع الأحوال ،تلتزم شركات التأمين بإخطار الهيئة بعمليات الغش
والاحتيال ) (Fraudالتي تتكشف لها عند الاكتتاب لعمليات تأمينات الأشخاص ،وذلك
 فور اكتشافها مع تضمين ما جاء بالقرار ضمن السياسة الاكتتابية بالشركة.$b199$
  FROM laws WHERE law_no = 2036 AND law_year = 2026
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
