WITH ins_art_alamiria_2026_25_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b209$نطاق التطبيق
تسري أحكام هذا القرار بشأن قواعد وإجراءات التأسيس والترخيص للشركات
الراغبة في ممارسة نشاط الخبرة الاستشارية في مجال التأمين ،وكذلك قواعد قيد
الأشخاص الطبيعيين الراغبين في ممارسة نشاط خبراء التأمين الاستشاريين بالسجل
 المعد لهذا الغرض لدى الهيئة .
ويعتبر استمرار توافر شروط ومتطلبات التأسيس والترخيص والقيد بالسجل
 صورة إ
للأشخاص الطبيعيين والاعتباريين على النحو المنصوص عليه بهذا القرار ،أحد
 شروط استمرار الترخيص /القيد بمزاولة النشاط .
 لك
وتكون الهيئة دون غيرها هي الجهة المختصة بالتأسيس والترخيص للشركات
 تروني
 الراغبة في ممارسة نشاط الخبرة الاستشارية في مجال التأمين .
كما تسري الأحكام الواردة في هذا القرار بشأن تنظيم ممارسة نشاط الخبرة
 ة ال يع
 الاستشارية فى مجال التأمين .$b209$
  FROM laws WHERE law_no = 25 AND law_year = 2026
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
