WITH ins_art_alamiria_2026_25_2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b210$تد بها
 تعريفات
خبير التأمين الاستشاري :كل شخص طبيعي أو اعتباري مرخص له من الهيئة
 عند ا
للقيام بأعمال الخبرة الاستشارية في مجال التأمين وعلى الأخص في الأمور الآتية :
إدارة وتقييم الأخطار ،وتقييم أصول والتزامات منشآت التأمين وإعادة التأمين ،وتقييم
 ل
 تداول
حقوق والتزامات المؤمن والمؤمن لهم ،وإعداد تقارير الخبرة الاستشارية للتأمين أمام
 المحاكم أو هيئات التحكيم أو غيرها من الجهات .
٥ الوقائع المصریة – العدد ) ٤٥تابع( فى ٢٤فبرایر سنة ٢٠٢٦
المنصة الإلكترونية للمهنيين :هي منصة منشأة من الهيئة لقيد وتجديد قيد
وإعادة قيد وتعديل بيانات أي من مزاولي المهن التأمينية المنصوص عليها بقانون
 التأمين الموحد ،بشكل إلكتروني .
القائم بالإدارة التنفيذية :هو الرئيس التنفيذي أو العضو المنتدب لشركة الخبرة
 الاستشارية في مجال التأمين .$b210$
  FROM laws WHERE law_no = 25 AND law_year = 2026
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
