-- ===== alamiria_2026_3 : قرار 3/2026 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (3, 2026, $t250$بتعديل قرار مجلس إدارة الهيئة رقم (2) لسنة 2025 بشأن قواعد وضوابط ونسب استثمار أموال شركات التأمين وإعادة التأمين$t250$, $t250$بتعديل قرار مجلس إدارة الهيئة رقم (2) لسنة 2025 بشأن قواعد وضوابط ونسب استثمار أموال شركات التأمين وإعادة التأمين$t250$, 'insurance', 'in_force', $u250$https://fra.gov.eg/wp-content/uploads/2026/02/alamiria_2026_3.pdf$u250$, NULL)
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

WITH ins_art_alamiria_2026_3_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b251$يستبدل بنص البند ) (٥من المادة الرابعة من قرار مجلس إدارة الهيئة رقم )(۲
 لسنة ٢٠٢٥المشار إليه ،النص الآتي :
 )المادة الرابعة /البند ": ("٥
 -٥إذا تبين للهيئة أن الأموال المخصصة طبق ًا لأحكام المادة ) (۱۷٥من قانون
التأمين الموحد غير كافية لمقابلة التزامات الشركة قبل حملة الوثائق والمستفيدين منها
عن عمليات التأمين المبرمة والمنفذة في جمهورية مصر العربية ،وجب على الشركة
استكمال هذا النقص فورا من الأموال الحرة المتاحة لديها ،وفي حال عدم كفاية
 الوقائع المصریة – العدد ٢٧تابع ) ب ( فى ٣فبرایر سنة ٢٠٢٦ ٤
الأموال الحرة تمنح الشركة مهلة لا تجاوز ثلاثة أشهر من التاريخ المحدد لتقديم
المركز المالي الذي تحقق فيه العجز مع التزام الشركة بتقديم خطة لاستيفاء العجز
 خلال المهلة الممنوحة .$b251$
  FROM laws WHERE law_no = 3 AND law_year = 2026
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
