-- ===== alamiria_2026_35 : قرار 35/2026 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (35, 2026, $t253$بشأن إلزام الشركات المرخص لها بمزاولة الأنشطة المالية غير المصرفية بإبرام وثيقة تأمين لتغطية مخاطر مسئولية مجالس إدارتها والمديرين التنفيذيين بها$t253$, $t253$بشأن إلزام الشركات المرخص لها بمزاولة الأنشطة المالية غير المصرفية بإبرام وثيقة تأمين لتغطية مخاطر مسئولية مجالس إدارتها والمديرين التنفيذيين بها$t253$, 'insurance', 'in_force', $u253$https://fra.gov.eg/wp-content/uploads/2026/02/alamiria_2026_35.pdf$u253$, NULL)
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

WITH ins_art_alamiria_2026_35_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b254$تلتزم الشركات المرخص لها من الهيئة بمزاولة الأنشطة المالية غير
المصرفية ،متى جاوز رأس مالها المصدر والمدفوع خمسين مليون جنيه ،بإبرام وثيقة
تأمين سنوية مع إحدى شركات التأمين العاملة في مصر لتغطية مخاطر مسئولية
مجلس إدارتها وكذا المديرين مسئولي الإدارة التنفيذية بها ،ويعد ذلك أحد شروط
 استمرار الترخيص بمزاولة النشاط.
ويتم تقدير حدود المسئولية بالوثيقة بما يتناسب مع حجم أعمال الشركة ودرجة
مخاطرها وبما لا يقل عن ) (٪٥من متوسط إيرادات الشركة خلال الثلاث سنوات
 المالية السابقة على تاريخ إصدار الوثيقة.
ويجب على الشركات المشار إليها تجديد الوثيقة سنويا ،وكذا الإفصاح بشكل
 فوري عن أي تعديل أو إلغاء يطرأ عليها خلال مدة سريانها.$b254$
  FROM laws WHERE law_no = 35 AND law_year = 2026
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
