INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (4, 2026, $t260$بشأن مد المهلة الممنوحة لزيادة رؤوس أموال بعض الشركات التى تزاول المهن والأنشطة المرتبطة بالتأمين$t260$, $t260$بشأن مد المهلة الممنوحة لزيادة رؤوس أموال بعض الشركات التى تزاول المهن والأنشطة المرتبطة بالتأمين$t260$, 'insurance', 'in_force', $u260$https://fra.gov.eg/wp-content/uploads/2026/02/alamiria_2026_4.pdf$u260$, NULL)
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

WITH ins_art_alamiria_2026_4_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b261$ت ُمد المهلة الممنوحة لزيادة رؤوس أموال الشركات التى تزاول أنشطة الوساطة
فى التأمين والوساطة فى إعادة التأمين وخبرة المعاينة وتقدير الأضرار وخبرة
الاستشارات التأمينية ،على النحو المنصوص عليه بقرار مجلس إدارة الهيئة
رقم ١٩٦لسنة ٢٠٢٤المشار إليه ،لمدة ستة أشهر أخرى اعتبارا من تاريخ انتهاء
 المدة الواردة بالقرار المذكور .
وتلتزم الشركات المشار إليها بإعداد جدول زمنى موضحا به مراحل زيادة
رؤوس أموالها وموافاة الهيئة به خلال شهر من تاريخ نشر هذا القرار ،ويحظر على
تلك الشركات توزيع أى أرباح نقدية على مساهميها قبل استيفاء متطلبات الحد الأدنى
 لرأس المال إلا بعد الحصول على عدم ممانعة الهيئة .$b261$
  FROM laws WHERE law_no = 4 AND law_year = 2026
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
