WITH ins_art___________________3973______2025_21 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 21, NULL, $b393$مع عدم الإخلال بالمواعيد المنصوص عليها في قانون التأمين الموحد
المشار إليه والقرارات الصادرة تنفيذ ًا له ،يلتزم الصندوق بموافاة الهيئة بالبيانات
 والمستندات الآتية :
 -١القوائم المالية السنوية والدورية وفق ًا للمواعيد المقررة من قبل الهيئة .
 -۲تقرير مراقب الحسابات متضمن ًا توضيح ما إذا كانت الحسابات الختامية
قد أعدت وفق ًا لمعايير المحاسبة المصرية وقرارات مجلس إدارة الهيئة المعمول بها
في هذا الشأن ومدى تعبيرها عن المركز المالي للصندوق تعبيرا صحيحا من واقع
سجلاتها والبيانات الأخرى التي رأى ضرورة الحصول عليها وإنها قد وضعت تحت
تصرفه ،وعلى أن يتضمن التقرير – حال وجود تحفظات -بيان مدى تأثيرها على
١٧ الجریدة الرسمیة – العدد ٤٣مكرر )ب( فى ٢٩أكتوبر سنة ٢٠٢٥
المركز المالي للصندوق ،ويجب على مراقب الحسابات أن يخطر الصندوق كتابة بأي
نقص أو خطأ أو أية مخالفات يكتشفها أثناء فحصه مع التزامه في ذات الوقت
 بإخطار الهيئة بذلك .
 -٣تقرير مجلس الإدارة عن حالة الصندوق ونشاطه خلال العام .
 -٤تقرير مجلس الإدارة عن أداء الاستثمار .
 -٥بيان عدد الاشتراكات الجديدة وقيمتها وعدد المشتركين وقيمة اشتراكاتهم
 وفق ًا للنموذج الذي تعده الهيئة في هذا الشأن .
 -٦بيان بعدد المطالبات التي قدمت للصندوق خلال العام وقيمتها ومقدار
 التعويضات التي تم سدادها خلال العام وتلك التي ما تزال تحت التسوية .
 -٧وفى حال التعامل مع شركات التأمين يتم موافاة الهيئة ببيان تلك الشركات
 والحصص المسندة إليها .$b393$
  FROM laws WHERE law_no = 3973 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
