WITH ins_art___________________3973______2025_22 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 22, NULL, $b394$يقدم الصندوق تقريرا اكتواريا إلى الهيئة بمركزه المالي يعده أحد الخبراء
الاكتواريين كل خمس سنوات على الأكثر يوضح فيه مدى كفاية أموال الصندوق
لمقابلة التزاماته وفق ًا للأسس الفنية التي تعتمدها الهيئة في هذا الخصوص ،ويتم إعداد
هذا التقرير وفق ًا للشروط والضوابط التي يصدرها مجلس إدارة الهيئة ،ولمجلس إدارة
الهيئة أن يطلب تقديم هذا التقرير في أي وقت قبل مضى خمس سنوات بحيث لا تقل
المدة عن سنة من تاريخ آخر تقرير ،على أن ترسل صورة منه إلى الهيئة خلال ستة
أشهر من انتهاء الفترة التي أعد عنها التقرير مصحوبة بشهادة من الخبير الاكتوارى
تثبت أن المسئولين عن إدارة الصندوق قد وضعوا تحت تصرفه جميع البيانات
والمعلومات التي طلبها ويراها ضرورية لأداء مهامه ،ويلتزم الخبير بإخطار الهيئة
بأي خطأ أو مخالفات قد تتكشف لديه أثناء إعداد التقرير الاكتواري ،وللهيئة مد هذا
الميعاد لفترة لا تزيد على ثلاثة أشهر ،وإذا تبين للهيئة أن تقرير الخبير الاكتوارى
لا يعبر عن حقيقة المركز المالي للصندوق فيلتزم الصندوق بإعادة إعداد التقرير
 بواسطة خبير اکتواري آخر على نفقة الصندوق .
 ويلتزم الصندوق في جميع الحالات بنفقات إعادة الفحص .
 الجریدة الرسمیة – العدد ٤٣مكرر )ب( فى ٢٩أكتوبر سنة ٢٠٢٥ ١٨$b394$
  FROM laws WHERE law_no = 3973 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
