WITH ins_art______________127______2025__________27 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 27, NULL, $b445$لا يجوز للشركة العضو طلب تغيير ممثلها بمجلس الإدارة بعد نجاحه وتزول
صفة ممثل الشركة بمجلس إدارة الاتحاد بالوفاة ،أو بانتهاء العلاقة بينه وبين الشركة
التى يمثلها ،أو إذا طلب العضو إنهاء تمثيله فى مجلس إدارة الاتحاد ،أو إذا فقد أحد
شروط الترشيح ،وفى أى من هذه الحالات تجرى عملية انتخاب جديدة لاختيار من
يحل محل الذى زالت صفته ،على أن يكون ممثلا ً لشركة تأمين تزاول نشاط ًا تأمينيا
من ذات طبيعة نشاط الشركة التى كان يمثلها العضو الذى زالت صفته ،وتكون مدة
 جديدة مكملة لمدة سلفه .$b445$
  FROM laws WHERE law_no = 127 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
