WITH ins_art______________198______2025__________5 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 5, NULL, $b520$التزامات وسيط التأمين الرقمي
 يلتزم وسيط التأمين الرقمي بما يلى :
 -١الإفصاح على المنصة الرقمية عن البيانات الخاصة بالترخيص الصادر له
بمزاولة النشاط وكذا موافقة الهيئة له على مباشرة أعمال الوساطة رقميا وفق ًا
 لهذا القرار .
 - ٢الإفصاح على المنصة الرقمية عن طبيعة الخدمات المقدمة للعملاء من
 خلال المنصة .
 -٣إعداد الإقرارات المناسبة واللازمة لاطلاع العميل وموافقته عليها قبل
 إصدار وثيقة التأمين .
 -٤إعداد قائمة بشركات التأمين التي تم الربط معها رقميا على المنصة الرقمية.
 صورة إ
 -٥إتاحة التواصل مع خدمة العملاء الخاصة بوسيط التأمين الرقمي بشكل
 مباشر من خلال المنصة .
 لك
 -٦إتاحة خاصية مقارنة المنتجات من ذات النوع لشركات التأمين المختلفة من
 تروني
 حيث الشروط والاستثناءات والأسعار بشكل محايد وموضوعي .
 -٧إتاحة الاطلاع على شروط ومزايا المنتجات التأمينية وموافقة العميل عليها
 ة ال يع
 قبل إصدار الوثيقة .
 -٨عدم تحصيل رسوم أو أقساط التأمين أو غيرها من المبالغ من العملاء بأي
 تد بها
وسيلة ينتج عنها إضافة تلك المبالغ إلى حساباته الخاصة ،ويلتزم بتحصيلها من خلال
ماكينات نقاط الدفع المسلمة إليه من شركة التأمين أو من خلال أي وسيلة دفع غير
 عند ا
 نقدي خاصة بالشركة .
 -٩الالتزام بمتطلبات الأمن السيبراني الواردة بقرار مجلس إدارة الهيئة
 ل
 تداول
رقم ١٣٩لسنة ، ۲۰۲۳وكذا أحكام قرار مجلس إدارة الهيئة رقم ١٤٠لسنة ٢٠٢٣
 المشار إليه .
٧ الوقائع المصریة – العدد ٢١٤تابع ) أ ( فى ٢٥سبتمبر سنة ٢٠٢٥
 -١٠إجراء اختبار اختراق للمنصة الإلكترونية ) (Penetration testمرة واحدة
على الأقل سنويا وكذا عند كل تغيير جوهري على الأنظمة التقنية ،على أن يتم موافاة
 الهيئة بنتائج ذلك الاختبار .
 - ١١إجراء اختبار الثغرات للمنصة الإلكترونية ) (Vulnerability testمرة
واحدة كل ثلاثة أشهر على الأقل وكذا عند كل تغيير جوهري على الأنظمة التقنية،
 على أن يتم موافاة الهيئة بنتائج ذلك الاختبار .
 -۱۲تطوير وتحديث المنصة الرقمية بصفة دورية أو كلما دعت الحاجة لذلك .
 - ۱۳موافاة الهيئة بأي بيانات أو مستندات تطلبها خلال الأجل الذي تحدده .$b520$
  FROM laws WHERE law_no = 198 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
