WITH ins_art______________199______2025__________4 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 4, NULL, $b528$الضوابط التنفيذية الواجب على شركات التأمين الالتزام بها عند إصدار وثائقها رقميا
تلتزم شركات التأمين بالضوابط التنفيذية الصادرة عن الهيئة عند إصدار وثائق
 التأمين وفق ًا لأحكام هذا القرار ،على أن تتضمن على وجه الأخص ما يلي :
 -۱شروط التعاقد بين شركة التأمين والجهة القائمة بالتسويق والتوزيع
 أو شروط إتاحة طلب الوثيقة مباشرة من قبل العميل .
 صورة إ
 -٢الحد الأدنى من البيانات والإرشادات الواجب عرضها على الشاشة الرقمية
 لطلب الوثيقة .
 لك
 -٣شروط الوثيقة الواجب الإفصاح عنها وتضمينها فيما يتم طباعته .
 تروني
 -٤أن سريان التغطية التأمينية مرتبط بالتحصيل الفعلي لشركة التأمين
 لأول قسط .
 ة ال يع
 - ٥جواز اقتصار دور الجهة القائمة بالتسويق والتوزيع على إدخال البيانات
الأساسية للعميل من خلال خط الربط الرقمي ،مع عدم السماح لها بإجراء أي تعديلات
 تد بها
سواء بالإضافة أو الحذف على شروط الوثيقة إلا من خلال شركة التأمين ذاتها وتحت
مسئوليتها ،على أن تلتزم شركة التأمين بالتحقق رقميا من صحة بيانات الرقم القومي
 عند ا
وملكية رقم الهاتف المحمول ومدى إدراجه في قوائم غسل الأموال والمنع من
التصرف على النحو المشار إليه بقرار مجلس إدارة الهيئة رقم ١٨٦لسنة ۲۰۲٤
 ل
 تداول
المشار إليه وذلك في كل مرة يقوم فيها العميل بإبرام وثيقة مع الشركة ،مع تعهد
 العميل بإبلاغ الشركة فور تغيير أي من بياناته التي قام بموافاة الشركة بها .
الوقائع المصریة – العدد ٢١٤تابع ) أ ( فى ٢٥سبتمبر سنة ١٣ ٢٠٢٥
 -٦التأكيد على أن يتم إخطار العملاء بأن الجهة القائمة بالتوزيع ما هي إلا قناة
للتسويق والتوزيع وغير مسئولة عن شروط وأحكام منتجات التأمين التي يتم تسويقها
 ولا عن سداد أية تعويضات ،وأن المسئولية تقع على شركة التأمين وحدها .
 -٧وجود مركز اتصال لدى شركة التأمين لخدمة عملاء التوزيع الرقمي لوثائق
التأمين والرد على استفساراتهم وتلقى الشكاوى الخاصة بهم ،على أن تتضمن النسخة
المطبوعة من الوثيقة رقم الهاتف والبريد الإلكتروني المحددين للتواصل مع مركز
 الاتصال المشار إليه .$b528$
  FROM laws WHERE law_no = 199 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
