WITH ins_art______________200______2025__________41 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 41, NULL, $b574$سياسات وقواعد الإفصاح والشفافية
يلتزم مجلس الإدارة بإعداد سياسات وقواعد الإفصاح والشفافية تتضمن
 -بحد أدنى -ما يلى :هدف السياسة ،ومجال تطبيقها ،ووسائل الإفصاح ،
 صورة إ
والمعلومات التى لا يجوز الإفصاح عنها ،والأشخاص المصرح لهم بالإفصاح ،
 والإجراءات الواجب اتخاذها فى حال حدوث إفصاح خاطئ عن المعلومات الجوهرية .
 لك
وتلتزم الشركة بتطبيق سياسات وقواعد الإفصاح والشفافية ،وعلى الأخص ما يلى :
 تروني
 -١إظهار جميع الحقائق والمعلومات المالية وغير المالية ،وكذا الأحداث
الجوهرية المتعلقة بالشركة لكافة الأطراف المعنية بشكل عادل وفى التوقيت المناسب
 ة ال يع
 بما يمكنهم من اتخاذ قراراتهم بناء على معلومات صحيحة ودقيقة .
 -٢أن تكون المعلومات التى يتم الإفصاح عنها مترابطة ،ودورية ،وموثقة ،
 تد بها
وشاملة ومفهومة وذات مصداقية ،وقابلة للقياس والمقارنة ،ومتاحة لكافة الأطراف
 فى التوقيت المناسب ودون تحملهم أى تكلفة إضافية .
 عند ا
 -٣الإفصاح لمساهمى الشركة والهيئة عن أهم المخاطر التى قد تواجه الشركة
وسبل التعامل معها والحد منها ،كما تلتزم بتحقيق مستوى ملائم من الشفافية ،
 ل
والإفصاح فى التوقيت المناسب عن أى أحداث من شأنها التأثير السلبى على المركز
 تداول
المالى أو الأداء المالى للشركة ،مع الأخذ فى الاعتبار عدم تأثير الإفصاح على
 قدرتها التنافسية فى الأسواق التى تزاول بها نشاطها .
 الوقائع المصریة – العدد ) ٢٣٥تابع( فى ٢١أكتوبر سنة ٢٠٢٥ ٤٢$b574$
  FROM laws WHERE law_no = 200 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
