-- ===== نشر-قرار-رقم-228-لسنة-2025-بالوقائع : قرار 228/2025 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (228, 2025, $t580$بشأن ضوابط استثمار شركات تأمينات الأشخاص وعمليات تكوين الأموال فى المعادن كأحد القيم المالية المنقولة$t580$, $t580$بشأن ضوابط استثمار شركات تأمينات الأشخاص وعمليات تكوين الأموال فى المعادن كأحد القيم المالية المنقولة$t580$, 'insurance', 'in_force', $u580$https://fra.gov.eg/wp-content/uploads/2025/11/%D9%86%D8%B4%D8%B1-%D9%82%D8%B1%D8%A7%D8%B1-%D8%B1%D9%82%D9%85-228-%D9%84%D8%B3%D9%86%D8%A9-2025-%D8%A8%D8%A7%D9%84%D9%88%D9%82%D8%A7%D8%A6%D8%B9.pdf$u580$, NULL)
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

WITH ins_art______________228______2025__________1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b581$مع عدم الإخلال بقرار مجلس إدارة الهيئة رقم ٢لسنة ۲۰۲٥المشار إليه ،
يجوز لشركات تأمينات الأشخاص وعمليات تكوين الأموال الاستثمار في المعادن
بشكل مباشر عند استثمار الأموال المقابلة للجزء الاستثماري من وثائق التأمين
 الوقائع المصریة – العدد ٢٤٧تابع )ج( فى ٤نوفمبر سنة ٢٠٢٥ ٤
أو الأموال المقابلة للعقود التي تصدرها الشركة لعمليات تكوين الأموال بحسب
الأحوال ،وذلك شريطة الحصول على موافقة الهيئة المسبقة على ذلك والالتزام
 بالضوابط الآتية :
 -١الحصول على موافقة مجلس إدارة الشركة ولجنة الاستثمار على قيام الشركة
بالاستثمار المباشر في المعادن كأحد القيم المالية المنقولة ،على أن تتضمن السياسة
الاستثمارية للشركة نوع المعادن الجائز الاستثمار فيها ،وطبيعة الإيرادات المستهدف
تحقيقها من ذلك الاستثمار ،والحد الأدنى من نسبة السيولة التي يتم الاحتفاظ بها
 لمواجهة ما ينشأ من التزامات .
 -٢أن يكون التعامل بيعا وشراء للمعادن من خلال الجهات المقيدة بالسجل
المعد لهذا الغرض بالهيئة وفق ًا لقرار مجلس إدارة الهيئة رقم ٥٢لسنة ٢٠٢٣
المشار إليه ،مع موافاة الهيئة بنسخة من العقد المبرم في هذا الشأن والحصول
 على عدم ممانعتها عليه .
 -٣أن يكون الاحتفاظ بالمعادن لدى أحد مقدمي خدمات حفظ المعادن المقيدين
لدى الهيئة وفق ًا لقرار مجلس إدارة الهيئة رقم ٥١لسنة ۲۰۲۳المشار إليه ،مع
موافاة الهيئة بنسخة من العقد المبرم في هذا الشأن والحصول على عدم ممانعتها عليه،
وفي حال التعامل مع أكثر من جهة للشراء فيجب الالتزام بفرز وتجنيب المعادن
 المشتراة من كل جهة على حدة .
 -٤التعاقد مع إحدى شركات خدمات الإدارة المرخص لها من الهيئة لتقييم
استثمارات الشركة في المعادن المستثمر فيها وفق ًا لأحكام هذا القرار مع موافاة الهيئة
 بنسخة من العقد المبرم في هذا الشأن والحصول على عدم ممانعتها عليه .
 -٥الحصول على موافقة العميل حال رغبته في توجيه جزء من قسط التأمين
للاستثمار في المعادن وفق ًا لأحكام هذا القرار ،وتعريفه بهذا النوع من الاستثمار
 وشروطه ومزاياه ومخاطره بشكل مكتوب ومن خلال فيديو تعريفي .
٥ الوقائع المصریة – العدد ٢٤٧تابع )ج( فى ٤نوفمبر سنة ٢٠٢٥
 -٦تضمين التقرير السنوي وربع السنوي الذي يجب على الشركة إعداده وفق ًا
لقرار مجلس إدارة الهيئة رقم ٢لسنة ٢٠٢٥المشار إليه ،إجمالي قيمة الأموال
المستثمرة في المعادن ،ونسبتها من إجمالي قيمة المحفظة الاستثمارية ،والعوائد
 المحققة بالمبالغ والمعدلات ،والتكاليف وذلك لكل معدن على حدة .$b581$
  FROM laws WHERE law_no = 228 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
