WITH ins_art______________229______2025__________11 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 11, NULL, $b595$السجلات التي يتعين على الشركة إمساكها
 تلتزم الشركات المخاطبة بأحكام هذا القرار بإمساك السجلات الآتية :
 -١سجل الوثائق ويتضمن الوثائق وجداول المزايا والمنافع التي تقوم
 الشركة بإدارتها .
 - ۲سجل العقود المبرمة مع شركات التأمين ومقدمي الخدمات الطبية،
ويتضمن أسماء الشركات وتاريخ بداية ونهاية التعاقد وما يرتبط بهذه العقود من
 تعديلات تتم عليها .
 صورة إ
 -٣سجل المخالصات التي تم استلامها من مقدم الخدمات الطبية .
 -٤سجل بالضمانات المقدمة لمقدمي الخدمات الطبية .
 لك
 -٥سجل الشكاوى التي ترد لها من المؤمن عليهم أو المستفيدين أو من مقدمي
 تروني
الخدمات الطبية ،ويتضمن تاريخ تقديم الشكوى ورقم مسلسل قيدها واسم مقدمها ،
 وبيان موجز بموضوعها وبيان بالمستندات المرفقة بها أو المقدمة تأييدا لها.
 ة ال يع
 -٦سجل الدعاوى القضائية أو التحكيمية المرفوعة ضد الشركة أو التي تكون
 طرف ًا فيها.
 تد بها
 -٧سجل تفصيلي بأرصدة الحسابات لكل شركة تأمين على حدة موضحا به
 المبالغ المستوفاة منها والمديونيات المعلقة بينهما.
 عند ا
 -٨سجل تفصيلي بالمطالبات التي ترد لها من مقدمي الخدمات الطبية لكل شركة
 تأمين على حدة ولكل عميل من عملاء البرامج ذاتية التمويل على حدة .
 ل
 تداول
 -٩سجل تفصيلي بالمطالبات المرفوضة لكل شركة تأمين على حدة ولكل عميل
 من عملاء البرامج ذاتية التمويل على حدة .
الوقائع المصریة – العدد ٢٥٤تابع )أ( فى ١٢نوفمبر سنة ١٧ ٢٠٢٥
وتلتزم الشركات بالاحتفاظ بالسجلات المشار إليها لمدة لا تقل عن خمس سنوات،
وذلك فيما عدا الحالات التي توجد بشأنها دعاوي قضائية أو تحكيمية ؛ فيجب على
الشركة اتخاذ الإجراءات اللازمة للاحتفاظ بالبيانات والمستندات الخاصة بموضوع
 الدعوى لحين صدور حكم نهائي فيها .
 كما يجوز الاحتفاظ بالسجلات المشار إليها بهذه المادة بشكل إلكتروني .$b595$
  FROM laws WHERE law_no = 229 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
