WITH ins_art______________4______2025__________1_2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b694$مخصص الأخطار السارية التزامات التغطية التأمينية المتبقية
يتم تكوين هذا المخصص لمقابلة التزامات الشركة عن عمليات التأمين المصدرة
من جملة اكتتاباتها وما زالت سارية بعد انتهاء السنة المالية وفق ًا لمعايير المحاسبة
 المصرية وذلك لعقود التأمين وإعادة التأمين .
ويراعي عند تطبيق طريقة نهج تخصيص الأقساط واتباع طريقة يوم بيوم
 أن تتضمن تقديرات المخصص ما يلي :
 (٪١٠٠) -١من رصيد أقساط وثائق التأمين طويلة الأجل والخاص بالسنوات
 التالية للسنة المالية المنقضية .
 (٪١٠٠) -٢من رصيد الأقساط المدفوع مقدما عن سنة مالية تالية .
 (٪١٠٠) -٣من أقساط الوثائق التي يبدأ تاريخ سريانها بعد انتهاء السنة المالية .
 -٤تخصم نسبة بحد أقصى ) (۲۰٪مقابل عمولات وتكاليف إنتاج )تكلفة الاستحواذ( .
 -٥يتم تكوين مخصص ضمن المخصص المشار إليه لمقابلة خسائر أية
مجموعة عقود محملة بخسارة وذلك عند تحقق بعض المؤشرات التي تفيد بذلك ومنها
زيادة معدل الخسارة التجميعي لتلك العقود على ) (٪١٠٠ويتم تكوينه بزيادة التزامات
 تلك العقود بنسبة الزيادة في معدل الخسارة التجميعي عن تلك النسبة .$b694$
  FROM laws WHERE law_no = 4 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
