WITH ins_art______________58______2025__________2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b703$التسجيل التاريخى على منصة الربط الإلكترونى
تلتزم شركات التأمين خلال مدة لا تجاوز ثلاثة أشهر من تاريخ العمل بهذا
القرار بتسجيل كافة بيانات سجلات الوثائق وملاحقها والتعويضات السارية اعتبارا
 من ٢٠٢٤/١/١وحتى تاريخ العمل بهذا القرار.
 الوقائع المصریة – العدد ) ٧٠تابع( فى ٢٥مارس سنة ٢٠٢٥ ٦
كما تلتزم شركات التأمين بتسجيل كافة نماذج عقود المنتجات التأمينية والتعديلات
والملاحق الخاصة بها السارية والمعمول بها والمعتمدة من الهيئة قبل ٢٠٢٥/١/١
 خلال مدة لا تجاوز ثلاثة أشهر من تاريخ العمل بهذا القرار .
وعلى الشركات المذكورة إدراج الأرقام التعريفية )الرقم القومى للأفراد -
رقم التسجيل الضريبى للشركات( للمستفيدين فى بيانات التعويضات ،وكذا إدراج الرقم
القومى لكافة العملاء الفرديين أو عملاء العقود الجماعية )المؤمن لهم والمؤمن عليهم(
عند إصدار الوثائق ،وإدراج الرقم القومى ورقم التسجيل الضريبى للجهات المتعاقد
معها للعقود الجماعية ،ويجوز للشركة بالنسبة للبيانات التاريخية التى لم يتوافر لديها
الأرقام التعريفية )الرقم القومى ورقم التسجيل الضريبي( للمؤمن عليهم وضع
رقم كودى للأفراد وهو ) (۹۹۹۹۹۹۹۹۹۹۹۹۹۹وللشركات ) (۹۹۹۹۹۹۹۹لإتمام
عملية التسجيل لحين قيام الشركة بتوفيق أوضاعها بإدراج الأرقام التعريفية الفعلية
للمؤمن عليهم خلال مدة لا تجاوز ستة أشهر من تاريخ العمل بهذا القرار مع تقديم
 تقرير شهرى للهيئة بما قامت به الشركة من أعمال التسجيل .$b703$
  FROM laws WHERE law_no = 58 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
