WITH ins_art______________77______2025__________4 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 4, NULL, $b761$التزامات شركات التأمين في مجال خدمة ما بعد البيع
تلتزم شركات التأمين بعد إبرام وثائق التأمين بضمان جودة خدمة العملاء
واستمراريتها ،ويجب عليها إخطار العملاء في الوقت المناسب وبالوسائل المتفق
 عليها معهم عند حدوث أي مما يلي :
 -١وجود تعديلات على وثائق التأمين أو أية تغييرات جوهرية تتعلق ببيانات
الشركة أو مركزها الرئيسي أو فروعها أو في حال تغيير مسئوليها أو ممثليها
المختصين بالتعامل مع المؤمن لهم ،ويجب أن تتصف الإخطارات بالوضوح ،
 والدقة ،والشفافية ،وأن ت ُرسل في التوقيت المناسب .
 -۲وجود أحداث جوهرية أو طارئة تؤثر في مركز الشركة المالي أو التأميني ؛
كحدوث قوة قاهرة ،أو انخفاض في معدلات العائد على الاستثمار ،أو تغير في أسعار
 صرف العملات الأجنبية ،أو ارتفاع في قيمة الشيء موضوع التأمين .
 صورة إ
 -٣الإخطار مسبق ًا عند رغبة الشركة إدخال أي تعديلات على الأحكام
أو الشروط المدرجة في الوثيقة ،مع تقديم مبررات واضحة لذلك خاصة إذا كان
 لك
التعديل متعلق ًا بسياسات الشركة ،مع بيان الأثر المتوقع على حقوق حملة الوثائق
 تروني
والمستفيدين منها ،ولا يجوز إجراء أي تعديل على الوثائق دون الحصول على موافقة
 كتابية مسبقة من المؤمن له أو حامل الوثيقة وبعد اعتمادها من الهيئة .
 ة ال يع
كما تلتزم شركات التأمين بإثبات أي تعديلات تطرأ على وثائق التأمين كتابة ،
 مع بيان واضح لأي مبالغ إضافية قد تترتب على المؤمن لهم نتيجة هذه التعديلات .$b761$
  FROM laws WHERE law_no = 77 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
