)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b769$السلوك والكفاءة المهنية
تلتزم شركات التأمين في إطار تعزيز السلوك والكفاءة المهنية للمتعاملين مع
 العملاء بما يلي :
 -١التأكد من تمتع وسطاء التأمين ومسئولي المبيعات بأعلى درجات الكفاءة
والمهنية والشفافية بما يمكنهم من أداء دورهم على النحو الأمثل في إقناع العملاء
 بأهمية المنتجات التأمينية ومساعدتهم على اختيار ما يتناسب مع احتياجاتهم التأمينية .
 -٢ممارسة العاملين بالشركة لأعمالهم بأسلوب مهني مسؤول يتصف بالنزاهة
والمصداقية وتحققهم من توافق المنتجات والخدمات المعتمدة للعملاء مع قدراتهم
المالية واحتياجاتهم التأمينية على نحو يحقق أفضل مصلحة للعملاء في كافة مراحل
تعاملهم مع الشركة ،مع تحمل الشركة المسؤولية الكاملة عن حماية العملاء فيما يقدم
 صورة إ
 إليهم من خدمات ومنتجات تأمينية .
 -٣توفير العاملين ذوي المؤهلات العلمية والكفاءات والمهارات اللازمة إلى
جانب تقديم التدريب الملائم والمستمر لهم خاصة لمن يتعاملون مباشرة مع العملاء مع
 لك
 تروني
 ضمان إلمامهم الكامل بطبيعة المنتجات والخدمات التأمينية المقدمة .
 -٤تقييم مستوى الكفاءة المهنية لوسطاء التأمين من خلال تقارير تقييم دورية
 ة ال يع
تعدها الشركة ،على أن تتضمن عناصر تلك التقارير آراء العملاء وتقييمهم لمستوى
الخدمات المقدمة ،ومدى اطلاعهم على كافة التفاصيل والمعلومات الواجب توفرها
 لدى المؤمن له .
 تد بها
 -٥التأكد من عدم ممارسة وسطاء التأمين لعملهم قبل الحصول على ترخيص
مزاولة مهنة الوساطة واستيفائهم كافة المتطلبات والشروط المهنية المطلوبة ،
 عند ا
بالإضافة إلى الاهتمام بتنمية قدراتهم المهنية عن طريق التدريب المستمر ،وكذلك
تقييمهم عن طريق اختبارات الكفاءة المهنية المتعارف عليها ،ومن خلال توافر نظم
 ل
 تداول
الرقابة الداخلية الفعالة ،مع التزامهم ببذل جهود فعالة لتقديم خدمات تأمينية تناسب
 احتياجات العملاء التأمينية وقدرتهم المالية .
 الوقائع المصریة – العدد ) ١٣٩تابع( فى ٢٥یونیة سنة ٢٠٢٥ ١٦
 -٦التأكد من قيام العاملين بالشركة بواجباتهم والتزاماتهم وتقديم الخدمات بأعلى
جودة وفي التوقيتات المناسبة ،بما يحقق مصلحة العملاء والمستفيدين طوال فترة
 المدة التأمينية .
 -٧تدريب الوسطاء والعاملين المعنيين بالتوزيع الإلكتروني على آليات التعامل
مع وثائق التأمين المصدرة إلكترونيا والخدمات المرتبطة بها ،مع تزويدهم
بالإرشادات اللازمة بما يضمن فهم متطلبات العملاء ويعزز من الشفافية والوضوح
 ويرفع من مستوى وعي المتعاملين .
 -٨التأكد من أن العاملين ممن يتعاملون مع العملاء والمستفيدين على إلمام كامل
بأفضل الممارسات المهنية في مجال تقديم الخدمات لعملاء شركات التأمين سواء التي
تصدر من خلال الهيئة للمهن المرتبطة أو من خلال الاطلاع على التجارب الدولية
 في هذا الشأن ،وبمراعاة القرارات الصادرة عن الهيئة .
 صورة إ
 -۹وضع سياسات محددة بشأن تجنب حالات تعارض المصالح ،وتحديد
 الإجراءات اللازمة لضمان التعامل العادل مع كافة العملاء .
 لك
 -١٠الإفصاح للعملاء عن أي تعارض محتمل في المصالح بين شركة التأمين
 تروني
 وأي أطراف أخرى ،إذا كان لهذا التعارض أثر محتمل على العملاء .
 وفي جميع الأحوال يحظر القيام بما يلي :
 ة ال يع
استقطاب العاملين بشركات التأمين لعملائهم حال الانتقال بين الشركات
 العاملة بالسوق .
 تد بها
حظر الاشتراك في الممارسة الخاصة بأسعار وثائق التأمين ،إذا كانت هذه
 الممارسة متصلة بمناقصة عامة أو محدودة لا تزال قائمة .
 عند ا$b769$, now()::date, 'active' FROM ins_art______________77______2025__________12;
WITH ins_art______________77______2025__________13 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 13, NULL, $b770$التزامات عملاء شركات التأمين
 ل
 تداول
يلتزم كافة عملاء شركات التأمين بالالتزام بمبدأ حسن النية عند استيفاء أي نماذج
أو مستندات تطلبها الشركة ،والامتناع عن تقديم أي بيانات أو معلومات مضللة
١٧ الوقائع المصریة – العدد ) ١٣٩تابع( فى ٢٥یونیة سنة ٢٠٢٥
أو خاطئة أو غير مكتملة ،أو الإخلال بواجب الإفصاح عن المعلومات الهامة
 أو الجوهرية لتجنب بطلان الوثيقة ،ويتعين عليهم القيام بما يلي :
 -١قراءة كافة المستندات المقدمة من الشركة بدقة والاطلاع عليها بعناية والتأكد
 من فهمها بشكل صحيح والتأكد من قدرتهم على الالتزام بمضمونها .
 -٢الاستفسار من الشركة في حال عدم وضوح أي بند أو شرط وارد في وثيقة
 التأمين أو في أي مستند آخر مقدم من الشركة .
 -٣التحقق من البيانات الواردة في طلبات ووثائق التأمين والتأكد من أنها
تتضمن كافة البيانات والمعلومات الأساسية والجوهرية ،ومنها على وجه الأخص ؛
البيانات الشخصية ،وتاريخ سريان التغطية ،وشروط وأحكام التأمين ،وبصفة خاصة
 شروط التصفية والإلغاء ،وحدود واستثناءات التغطيات ،وملاحق الوثائق .
 -٤معرفة طرق تقديم الشكاوى سواء للهيئة أو الشركة .
 صورة إ
 -٥عدم استخدام المنتجات أو الخدمات التأمينية إلا وفق ًا للشروط والأحكام
 الواردة في وثائق التأمين .
 لك
 -٦الامتناع عن طلب منتجات أو خدمات تأمينية لا تتلاءم مع أوضاعهم المالية ،
 تروني
أو مستوى تقبلهم للمخاطر ،أو عدم القدرة على الوفاء بالالتزامات المترتبة على
 الحصول على تلك المنتجات والخدمات التأمينية .
 ة ال يع
 -٧إبلاغ الشركة عن الإجراءات غير المعتادة في المنتجات أو الخدمات المقدمة
 لهم ،وإخطار الهيئة في حال عدم تجاوب الشركة .
 تد بها
 -٨الرجوع إلى الشركة في حال عدم قدرتهم على الوفاء بالتزاماتهم التأمينية
 لمعرفة الخيارات البديلة المتاحة بما يتناسب مع وضعهم المالي .
 عند ا
 -٩استخدام وسائل التواصل الشخصية والمحددة في العقد المبرم مع الشركة ،
 والامتناع عن استخدام وسائل تواصل لا تخصهم .
 ل
 تداول
 - ١٠تحديث بياناتهم الشخصية بما في ذلك بيانات الاتصال الخاصة بهم ،بشكل
 مستمر أو عند طلب الشركة ذلك .
 الوقائع المصریة – العدد ) ١٣٩تابع( فى ٢٥یونیة سنة ٢٠٢٥ ١٨
 -۱۱عدم التوقيع على نماذج غير مكتملة ،والتأكد من اكتمال كافة البيانات
والمعلومات الواردة في النماذج قبل التوقيع عليها ،وعدم التوقيع على نماذج فارغة
 أو غير مكتملة .
 -١٢مراجعة المعلومات والبيانات التي قاموا بإدخالها ضمن نماذج
طلبات المنتجات أو الخدمات التأمينية؛ لضمان دقتها وخلوها من الأخطاء ،وذلك قبل
 التوقيع عليها .
 -١٣عدم الإفصاح عن معلوماتهم الشخصية أو التأمينية لأي جهة غير الشركة
 أو الجهات الرسمية المختصة .
 - ١٤تزويد الشركات بكافة المعلومات الجوهرية لتحديد احتياجاتهم التأمينية
 وتقييم المخاطر المرتبطة بها .
 صورة إ
 -١٥التأكد من الحصول على نسخ معتمدة من العقود والمستندات الموقعة
والاحتفاظ بها في مكان آمن ،وفي حال الوثائق الإلكترونية يحق للمؤمن لهم طلب
 لك
نسخ ورقية موقعة ومختومة من الشركة أو طلب إرسالها لهم عبر البريد المسجل
 تروني
 خلال مدة لا تتجاوز سبعة أيام عمل من تاريخ تقديم الطلب .$b770$
  FROM laws WHERE law_no = 77 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
