-- ===== نشر-قرار-رقم-89-لسنة-2025-بالوقائع : قرار 89/2025 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (89, 2025, $t803$بشأن الشروط والمعايير الواجب توافرها فى أعضاء مجالس إدارة شركات التأمين أو إعادة التأمين، والشروط والمعايير الواجب توافرها فى القائمين على الإدارة التنفيذية المسئولين عن الأعمال والوظائف الفنية$t803$, $t803$بشأن الشروط والمعايير الواجب توافرها فى أعضاء مجالس إدارة شركات التأمين أو إعادة التأمين، والشروط والمعايير الواجب توافرها فى القائمين على الإدارة التنفيذية المسئولين عن الأعمال والوظائف الفنية$t803$, 'insurance', 'in_force', $u803$https://fra.gov.eg/wp-content/uploads/2025/06/نشر-قرار-رقم-89-لسنة-2025-بالوقائع.pdf$u803$, NULL)
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

WITH ins_art______________89______2025__________1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b804$نطاق التطبيق
تسرى أحكام هذا القرار فى شأن الشروط والمعايير الواجب توافرها فى أعضاء
مجالس إدارة شركات التأمين أو إعادة التأمين ،وكذا الشروط والمعايير الواجب
توافرها فى القائمين على الإدارة التنفيذية المسئولين عن أى من الأعمال والوظائف
الفنية بتلك الشركات ،وكذا فى شأن أى جهات أو أشخاص أخرى يسرى فى شأنهم
 ذات الشروط والمعايير .$b804$
  FROM laws WHERE law_no = 89 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b804$نطاق التطبيق
تسرى أحكام هذا القرار فى شأن الشروط والمعايير الواجب توافرها فى أعضاء
مجالس إدارة شركات التأمين أو إعادة التأمين ،وكذا الشروط والمعايير الواجب
توافرها فى القائمين على الإدارة التنفيذية المسئولين عن أى من الأعمال والوظائف
الفنية بتلك الشركات ،وكذا فى شأن أى جهات أو أشخاص أخرى يسرى فى شأنهم
 ذات الشروط والمعايير .$b804$, now()::date, 'active' FROM ins_art______________89______2025__________1;
WITH ins_art______________89______2025__________2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b805$الشروط الواجب توافرها فى أعضاء مجالس إدارة شركات التأمين
 أو إعادة التأمين
يجب أن يتوافر فى المرشح لعضوية مجلس إدارة أى من شركات التأمين
 أو إعادة التأمين الشروط الآتية :
 -١أن يكون محمود السيرة ،حسن السمعة .
 -٢ألا يقوم به عارض من عوارض الأهلية .
 الوقائع المصریة – العدد ) ١٢٨تابع( فى ١٢یونیة سنة ٢٠٢٥ ٥٢
 -٣أن يكون متمتعا بحقوقه المدنية كاملة .
 -٤أن يكون حاصلا ً على مؤهل عال مناسب من إحدى الجامعات المصرية
 أو الأجنبية شريطة معادلته فى مصر أو موافقة الهيئة عليه .
 -٥ألا يكون قد سبق الحكم عليه بحكم بعقوبة جناية ،أو بعقوبة جنحة فى
جريمة ماسة بالشرف أو الأمانة أو فى إحدى الجرائم المنصوص عليها فى قوانين
الشركات أو القوانين المنظمة للأنشطة المالية غير المصرفية ،أو قانون مكافحة غسل
الأموال ،أو حكم بإشهار إفلاسه ،وذلك خلال الخمس سنوات السابقة على تاريخ
 تقديم طلب الترشح ما لم يكن قد رد إليه اعتباره .
 -٦ألا يكون قد صدر ضده أو ضد إحدى الشركات العاملة فى مجال الأنشطة
المالية غير المصرفية التى كان يشغل رئاسة أو عضوية مجلس إدارتها أو يعمل لديها ،
ثمة تدابير إدارية نتيجة مخالفات جسيمة خلال الثلاث سنوات السابقة على تاريخ تقديم
 طلب الترشح وكان ذلك بسبب إخلاله بواجباته ومسئولياته .
 -٧ألا يكون قد سبق فصله عن العمل أو شطبه من سجل إحدى المهن لأمور
 ماسة بالشرف أو الأمانة ،ما لم يمض على ذلك ثلاث سنوات .
 -٨أن يتمتع بالاستقلالية اللازمة لأداء مهامه وواجباته ،وألا يكون لديه مصالح
تتعارض مع واجبات رئاسة أو عضوية مجلس إدارة الشركة أو تؤثر على قدرته فى
القيام بذلك ،على أن يتم الإفصاح عن مدى وجود أية صلة قرابة حتى الدرجة الرابعة
 بين المرشحين بأحد المسئولين الرئيسيين بالشركة .
 -٩الإلمام بالتشريعات الصادرة فى مجال التأمين ،وأن يتوافر لديه شروط
 الخبرة الآتية :
) أ ( بالنسبة للمرشح لتولى منصب رئيس مجلس إدارة الشركة :عشر سنوات
على الأقل فى مجال التأمين أو إعادة التأمين أو الخبرة الاكتوارية أو فى
إحدى المجالات القانونية أو المحاسبية أو المالية أو الاستثمارية أو إدارة
الأعمال أو تكنولوجيا المعلومات المتعلقة بمجال عمل الشركة أو المجالات
 الطبية إذا كانت الشركة من شركات التأمين الطبى المتخصص .
٥٣ الوقائع المصریة – العدد ) ١٢٨تابع( فى ١٢یونیة سنة ٢٠٢٥
)ب( بالنسبة للمرشحين من ذوى الخبرة :خمس عشرة سنة فى مجال التأمين
أو إعادة التأمين أو الخبرة الاكتوارية أو فى إحدى المجالات المالية
أو الاستثمارية المتعلقة بمجال عمل الشركة ،ويجب أن يكون العضو
 المنتدب للشركة من ذوى الخبرة .
وللهيئة تخفيض مدة الخبرة المتطلبة فى المرشحين من ذوى الخبرة بناء
 على الشهادات العلمية أو المهنية الحاصل عليها المرشح .
)ج( بالنسبة للمرشحين لعضوية مجلس الإدارة بخلاف المشار إليهم بالبندين
)أ ،ب( :خمس سنوات على الأقل فى إحدى المجالات المشار إليها بالبند
 )أ( أو أى مجالات أخرى توافق عليها الهيئة .
وفى جميع الأحوال ،يجب مراعاة التنوع فى مجالات الخبرة فى تشكيل
 مجلس إدارة الشركة .
 -١٠ألا يكون عضوا فى مجلس إدارة شركة تأمين أخرى تمارس ذات النشاط
ما لم تكن شركة تابعة أو شقيقة وبموافقة الجمعية العامة للشركة المرشح لعضوية
مجلس إدارتها ،وذلك ما لم يقدم تعهدا بالاستقالة من عضوية مجلس إدارة الشركات
 المشار إليها فور فوزه بعضوية مجلس الإدارة .
 -١١ألا يشغل المرشح لمنصب العضو المنتدب عضوية مجلس إدارة لأكثر من
ثلاث شركات تساهم فيها الشركة التى يمثلها فى ذات الوقت ،وذلك ما لم يقدم تعهدا
بالاستقالة من عضوية مجلس إدارة ما زاد على الشركات المشار إليها فور فوزه
 بعضوية مجلس الإدارة .
ويجوز أن يشغل عضوية مجلس إدارة شركات أخرى بخلاف الشركات المشار
إليها بهذا البند شريطة عدم وجود تعارض فى المصالح وبعد الحصول على عدم
 ممانعة الهيئة .
 -١٢اجتياز رئيس مجلس الإدارة والعضو المنتدب للمقابلة الشخصية الذى
تعقدها الهيئة فى هذا الشأن ،ويجوز للهيئة إجراء مقابلة شخصية مع باقى المرشحين
لعضوية مجلس إدارة الشركة ،ويجوز أن تتم هذه المقابلات بإحدى الوسائل
 الإلكترونية .
 الوقائع المصریة – العدد ) ١٢٨تابع( فى ١٢یونیة سنة ٢٠٢٥ ٥٤
ويشترط لاستمرار العضوية بمجلس إدارة الشركة استمرار توافر البنود )، ٢ ، ١
 (١١ ، ١٠ ، ٨ ، ٥ ، ٣من هذه المادة ،وفى حال فقد العضو أى منها تزول
عضويته بمجلس إدارة الشركة ،ويتعين على مجلس إدارة الشركة اتخاذ الإجراءات
 اللازمة حيال ذلك .$b805$
  FROM laws WHERE law_no = 89 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
