WITH ins_art______________89______2025__________3 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 3, NULL, $b806$إجراءات اختيار أعضاء مجلس إدارة الشركة
ت ُتبع الإجراءات الآتية عند اختيار أعضاء مجالس إدارة شركات التأمين
 أو إعادة التأمين :
 -١تقوم الشركة بموافاة الهيئة قبل انعقاد الجمعية العامة بستين يوما على الأقل
بتقرير يتضمن أسماء المرشحين لرئاسة وعضوية مجلس إدارة الشركة وأسباب تحقق
أو تخلف شروط الترشح فى شأنهم والمستندات المؤيدة لذلك ؛ بما فيها صورة بطاقة
الرقم القومى ،والسيرة الذاتية لهم ،وصور من الشهادات العلمية والمهنية الحاصل
عليها المرشح ،على أن تلتزم الشركة والمرشحين بإخطار الهيئة فورا حال حدوث
أى تغيير فى البيانات المقدمة ،وكذا إذا تبين للشركة عدم صحة أى من المستندات
 أو البيانات المقدمة .
 -٢تقوم الهيئة بفحص طلبات المرشحين والتأكد من استيفاء الشروط المتطلبة
فى شأنهم واستيفاء البند ) (١٢من المادة الثانية من هذا القرار ،وللهيئة مخاطبة
الشركة أو المرشحين لاستيفاء أى بيانات أو مستندات ترى ضرورة تقديمها للبت
 فى طلب الترشح .
 -٣تقوم الهيئة بإخطار الشركة بأسماء المقبولين ممن تتوافر فيهم شروط الترشح
لعضوية مجلس إدارة الشركة ،على أن تلتزم الشركة بإخطار المتقدمين بنتيجة الفحص
 خلال يومى عمل على الأكثر ،ونشر أسماء المقبولين على الموقع الإلكترونى لها .
 -٤تقوم الشركة بعرض الأسماء الواردة إليها من الهيئة على الجمعية العامة
للانتخاب أو النظر فى تعيين أعضاء مجلس إدارة الشركة بحسب الأحوال ،على أن
تقوم الشركة بموافاة الهيئة بتشكيل مجلس إدارتها الجديد خلال عشرة أيام عمل من
 تاريخ انعقاد الجمعية العامة .
٥٥ الوقائع المصریة – العدد ) ١٢٨تابع( فى ١٢یونیة سنة ٢٠٢٥$b806$
  FROM laws WHERE law_no = 89 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
